llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C61"],
      "claim": "Didanosine, a closely related purine dideoxynucleoside, has approximately 40% oral bioavailability in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Zalcitabine, another dideoxynucleoside, has a mean oral bioavailability of 88% in patients, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C67"],
      "claim": "Zidovudine, a modified nucleoside, has absolute oral bioavailability of 62–68% in adults, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Lamivudine, a polar nucleoside analog, has oral bioavailability of 87% as an oral solution, showing that polar nucleosides can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Viramidine, a full-ribose ribonucleoside, has 66.1% oral bioavailability in humans, directly relevant to the ribose-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "One didanosine study reports ~19% ± 17% oral bioavailability, providing some contradictory evidence near the threshold, but this is variable and dose/condition-dependent.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of highly transferable nucleoside analogue evidence indicates oral bioavailability above 20%: didanosine ~40%, zalcitabine 88%, zidovudine ~60%, lamivudine >80%, and viramidine 66%. The few sub-20% didanosine values are dose/fed-condition dependent and do not overturn the consistent high-F pattern. Therefore predict high.",
  "evidence_gaps": [
    "No direct oral bioavailability data for xanthosine itself.",
    "Potential first-pass cleavage by purine nucleoside phosphorylase is not directly captured by the analogue records.",
    "Dose/saturable absorption effects seen for didanosine may not translate exactly to the full ribose query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

